#!/usr/bin/env python3
#sequencia oferecida no desafio
DNA = ""

#colocando o local de corte da EcoRI
DNA = DNA.replace("GAATTC", "G^AATTC")

posicoes = []

#procurando onde estao os cortes
for i in range(len(DNA)):
    if DNA[i] == "^":
        posicoes.append(i)

#tirando os ^da sequencia
DNA = DNA.replace("^", "")

fragmentos = []
inicio = 0

#separando os fragmentos
for posicao in posicoes:
    fragmentos.append((inicio + 1, posicao, DNA[inicio:posicao]))
    inicio = posicao

#adicionando o ultimo fragmento
fragmentos.append((inicio + 1, len(DNA), DNA[inicio:]))

#imprimindo os fragmentos ordenados como no gel de agarose (do maior para o menor)
fragmentos = sorted(fragmentos, key=lambda x: len(x[2]), reverse=True)
for inicio, fim, fragmento in fragmentos:
    print(inicio, fim, len(fragmento), sep="\t")
